"""RAG pipeline integration template — generates services/rag_service.py."""
from __future__ import annotations


def generate_rag_service(output_dir=None, config: dict | None = None) -> str:
    """Return production-ready RAG service code as a string."""
    return '''\
"""RAG (Retrieval-Augmented Generation) service — generated by AetherOS p04c.

Uses ChromaDB if available, falls back to in-memory vector store.
Reads EMBEDDING_MODEL from env (default: text-embedding-3-small).
Requires LLM_API_KEY (+ LLM_BASE_URL for a non-OpenAI endpoint) for embeddings and chat.
"""
from __future__ import annotations
import hashlib
import logging
import os
from typing import Any, Dict, List, Optional

logger = logging.getLogger(__name__)

_EMBEDDING_MODEL = os.getenv("EMBEDDING_MODEL", "text-embedding-3-small")
_OPENAI_KEY = os.getenv("LLM_API_KEY") or os.getenv("OPENAI_API_KEY", "")
_BASE_URL = os.getenv("LLM_BASE_URL") or None
_COLLECTION_NAME = os.getenv("RAG_COLLECTION", "rag_documents")


# ---------------------------------------------------------------------------
# In-memory fallback vector store
# ---------------------------------------------------------------------------

class _InMemoryStore:
    """Simple cosine-similarity in-memory vector store (no dependencies)."""

    def __init__(self) -> None:
        self._docs: List[Dict[str, Any]] = []

    def add(self, doc_id: str, embedding: List[float], content: str, metadata: Dict) -> None:
        self._docs.append({"id": doc_id, "embedding": embedding, "content": content, "metadata": metadata})

    def query(self, embedding: List[float], top_k: int = 5) -> List[Dict]:
        if not self._docs:
            return []
        import math

        def cosine(a, b):
            dot = sum(x * y for x, y in zip(a, b))
            na = math.sqrt(sum(x * x for x in a))
            nb = math.sqrt(sum(y * y for y in b))
            return dot / (na * nb) if na and nb else 0.0

        scored = [(cosine(embedding, d["embedding"]), d) for d in self._docs]
        scored.sort(key=lambda x: x[0], reverse=True)
        return [d for _, d in scored[:top_k]]


class RAGService:
    """Retrieval-Augmented Generation service with ChromaDB or in-memory backend."""

    def __init__(self) -> None:
        self._store: Any = None
        self._chroma = False
        self._openai_client = None
        self._init_store()

    def _init_store(self) -> None:
        """Try ChromaDB first, fall back to in-memory store."""
        try:
            import chromadb
            client = chromadb.Client()
            self._store = client.get_or_create_collection(_COLLECTION_NAME)
            self._chroma = True
            logger.info("RAGService: using ChromaDB collection=%s", _COLLECTION_NAME)
        except Exception as exc:
            logger.warning("RAGService: ChromaDB unavailable (%s) — using in-memory store", exc)
            self._store = _InMemoryStore()

    def _get_openai(self):
        if self._openai_client is None:
            try:
                from openai import OpenAI
                self._openai_client = OpenAI(api_key=_OPENAI_KEY, base_url=_BASE_URL)
            except ImportError as exc:
                raise RuntimeError("openai package not installed: pip install openai") from exc
        return self._openai_client

    def _embed(self, text: str) -> List[float]:
        """Return embedding vector for text using OpenAI embeddings."""
        client = self._get_openai()
        resp = client.embeddings.create(model=_EMBEDDING_MODEL, input=text)
        return resp.data[0].embedding

    def ingest_document(self, content: str, metadata: Optional[Dict] = None) -> str:
        """Ingest a document into the vector store. Returns the document ID."""
        doc_id = hashlib.sha256(content.encode()).hexdigest()[:16]
        meta = metadata or {}
        try:
            embedding = self._embed(content)
            if self._chroma:
                self._store.upsert(
                    ids=[doc_id],
                    embeddings=[embedding],
                    documents=[content],
                    metadatas=[meta],
                )
            else:
                self._store.add(doc_id, embedding, content, meta)
            logger.info("RAGService: ingested doc id=%s len=%d", doc_id, len(content))
            return doc_id
        except Exception as exc:
            logger.warning("RAGService.ingest_document failed: %s", exc)
            raise

    def search(self, query: str, top_k: int = 5) -> List[Dict[str, Any]]:
        """Search for documents relevant to a query. Returns list of result dicts."""
        try:
            embedding = self._embed(query)
            if self._chroma:
                results = self._store.query(query_embeddings=[embedding], n_results=top_k)
                docs = results.get("documents", [[]])[0]
                metas = results.get("metadatas", [[]])[0]
                return [{"content": d, "metadata": m} for d, m in zip(docs, metas)]
            else:
                hits = self._store.query(embedding, top_k=top_k)
                return [{"content": h["content"], "metadata": h["metadata"]} for h in hits]
        except Exception as exc:
            logger.warning("RAGService.search failed: %s", exc)
            return []

    def chat_with_context(self, query: str, top_k: int = 5, system: str = "") -> str:
        """Answer a query using retrieved context (RAG pattern)."""
        try:
            docs = self.search(query, top_k=top_k)
            context = "\\n\\n---\\n\\n".join(d["content"] for d in docs)
            client = self._get_openai()
            system_prompt = system or (
                "You are a helpful assistant. Answer the user\'s question "
                "using only the context below. If the answer is not in the context, "
                "say you don\'t know."
            )
            messages = [
                {"role": "system", "content": system_prompt + f"\\n\\nContext:\\n{context}"},
                {"role": "user", "content": query},
            ]
            resp = client.chat.completions.create(
                model=os.getenv("LLM_MODEL") or os.getenv("AI_MODEL", "gpt-4o-mini"),
                messages=messages,
                max_tokens=800,
            )
            return resp.choices[0].message.content or ""
        except Exception as exc:
            logger.warning("RAGService.chat_with_context failed: %s", exc)
            raise


rag_service = RAGService()
'''
